el-parceiro-core' ) : $meta['invoice_billing_type'] ); ?></div></div><div class="invoice-item d-flex justify-content-between mb-3"><div class="fw-bold"><?php esc_html_e( 'Método de pagamento', 'imovel-parceiro-core' ); ?></div><div class="text-end"><?php echo esc_html( $meta['invoice_payment_method'] ); ?></div></div><div class="invoice-item d-flex justify-content-between"><div class="fw-bold"><?php esc_html_e( 'Preço total', 'imovel-parceiro-core' ); ?></div><div class="text-end fw-bold"><?php echo wp_kses_post( houzez_get_invoice_price( $meta['invoice_item_price'] ) ); ?></div></div></div><?php $additional = houzez_option( 'invoice_additional_info' ); if ( $additional ) : ?><div class="invoice-description mt-4 p-3 bg-light rounded"><div class="text-inner"><p class="fw-bold"><?php esc_html_e( 'Informações adicionais', 'imovel-parceiro-core' ); ?></p><p><?php echo wp_kses_post( $additional ); ?></p></div></div><?php endif; ?></div></div></div></div>
